begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s4_fixture.sql
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(public.get_s4_capabilities()->>'atomic_confirmation'='true','S4 capability activated');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->'availability'->>'eligible_count'='2','NULL profile is excluded from quorum');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',null,pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='S4004','cannot advance while members have not submitted');
select pg_temp.check(pg_temp.s4_submit('24000000-0000-4000-8000-000000000001')->>'outcome'='applied','owner submits future KST slots');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.s4_submit('24000000-0000-4000-8000-000000000001')->>'outcome'='applied','mate submits future KST slots');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',(select v from s4_data where k='time'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),gen_random_uuid())$q$)='42501','mate cannot select time');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('select',public.select_room_meeting_time_v1('24000000-0000-4000-8000-000000000001',(select v from s4_data where k='time'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000001'));
select pg_temp.check((select v->'state'->>'stage'='place' and v->'state'->>'time_status'='selected' from s4_data where k='select'),'time and stage persist atomically');
insert into s4_data values('menu',to_jsonb(public.add_voting_item('24000000-0000-4000-8000-000000000001','menu','Synthetic restaurant')));
select pg_temp.check(public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='menu')),'owner votes');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(public.toggle_vote('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='menu')),'mate votes');
select pg_temp.check(public.get_room_s4_state('24000000-0000-4000-8000-000000000001')->>'stage'='place','all votes never auto-confirm');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into s4_data values('before-confirm-revision',to_jsonb(pg_temp.s4_revision('24000000-0000-4000-8000-000000000001')));
insert into s4_data values('confirmed',public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='menu'),pg_temp.s4_revision('24000000-0000-4000-8000-000000000001'),'64000000-0000-4000-8000-000000000002'));
select pg_temp.check((select v->'state'->>'confirmation_status'='owner_confirmed' and v->'state'->>'stage'='confirmed' from s4_data where k='confirmed'),'owner atomically confirms appointment');
select pg_temp.check(public.confirm_room_appointment_v1('24000000-0000-4000-8000-000000000001',(select (v#>>'{}')::uuid from s4_data where k='menu'),(select (v#>>'{}')::bigint from s4_data where k='before-confirm-revision'),'64000000-0000-4000-8000-000000000002')->>'outcome'='replayed','same request replays before stale revision/stage checks');
select pg_temp.check(public.advance_room_stage('24000000-0000-4000-8000-000000000001','confirmed')='confirmed','legacy follow-up advance is a no-op');
reset role;
select pg_temp.check((select count(*)=1 from public.messages where event_key='appointment-confirmed:24000000-0000-4000-8000-000000000001'),'exactly one system event');
select pg_temp.check((select confirmed_menu='Synthetic restaurant' and location_name=confirmed_menu and is_confirmed and appointment_confirmed_by='10000001-0000-4000-8000-000000000001' from public.rooms where id='24000000-0000-4000-8000-000000000001'),'canonical restaurant and owner evidence agree');
select * from finish();
rollback;
